"""Builds supabase/seed.sql from packs/*.json so the JSON stays the single source of truth.

uv run python -m app.db_seed           # write supabase/seed.sql
uv run python -m app.db_seed --check   # exit 1 if seed.sql is out of date (CI)
"""

import argparse
import json
import sys
from pathlib import Path
from typing import Any

from app.core.config import REPO_ROOT
from app.engine.packs import parse_pack

PACKS_DIR = REPO_ROOT / "packs"
SEED_PATH = REPO_ROOT / "supabase" / "seed.sql"

_HEADER = """\
-- GENERATED by apps/api/app/db_seed.py from packs/*.json. Do not edit by hand:
-- change the JSON, then run `make db-reset` (or `uv run python -m app.db_seed`).
"""


def _read_json(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))


def load_pack_rows(packs_dir: Path = PACKS_DIR) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = [_read_json(packs_dir / "career_sprint.json")]
    rows.extend(_read_json(packs_dir / "coming_soon.json"))
    for row in rows:
        parse_pack(row)
    return sorted(rows, key=lambda r: (r["sort_order"], r["id"]))


def _literal(value: str) -> str:
    return "'" + value.replace("'", "''") + "'"


def render_seed(packs_dir: Path = PACKS_DIR) -> str:
    packs = load_pack_rows(packs_dir)
    events = _read_json(packs_dir / "calendar_events.json")

    pack_values = ",\n".join(
        f"  ({_literal(p['id'])}, {_literal(p['name'])}, {_literal(p['status'])}, "
        f"{int(p['sort_order'])}, {_literal(json.dumps(p, ensure_ascii=False))}::jsonb)"
        for p in packs
    )
    event_values = ",\n".join(
        f"  ({_literal(e['date'])}, {_literal(e['name'])}, {_literal(e['kind'])})" for e in events
    )
    return (
        f"{_HEADER}\n"
        "insert into packs (id, name, status, sort_order, config) values\n"
        f"{pack_values}\n"
        "on conflict (id) do update set name = excluded.name, status = excluded.status,\n"
        "  sort_order = excluded.sort_order, config = excluded.config, updated_at = now();\n\n"
        "insert into calendar_events (date, name, kind) values\n"
        f"{event_values}\n"
        "on conflict (date, name) do nothing;\n"
    )


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail if seed.sql is out of date")
    args = parser.parse_args(argv)
    expected = render_seed()
    if args.check:
        current = SEED_PATH.read_text(encoding="utf-8") if SEED_PATH.exists() else ""
        if current != expected:
            print("supabase/seed.sql is out of date: run `uv run python -m app.db_seed`")
            return 1
        return 0
    SEED_PATH.write_bytes(expected.encode("utf-8"))
    print(f"wrote {SEED_PATH.relative_to(REPO_ROOT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
